import { Component, Suspense, lazy } from "react";

// Error Boundary: bắt lỗi khi RENDER của cây con (phải là class)
class ErrorBoundary extends Component {
  state = { error: null };
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) { console.error("Bắt lỗi:", error.message); }   // gửi tới Sentry ở sản xuất
  render() {
    return this.state.error ? <p id="fallback">Có lỗi xảy ra, vui lòng thử lại.</p> : this.props.children;
  }
}

function Bomb() { throw new Error("nổ!"); }

// lazy: tải mã của component khi cần (ở đây giả lập)
const Heavy = lazy(() => new Promise((res) => setTimeout(() => res({ default: () => <p id="heavy">Đã tải xong</p> }), 50)));

export default function App() {
  return (
    <div>
      <ErrorBoundary><Bomb /></ErrorBoundary>
      <Suspense fallback={<p id="wait">Đang tải…</p>}><Heavy /></Suspense>
    </div>
  );
}

